export interface BlogArticleSection {
  id: string;
  title: string;
  bluf?: string;
  paragraphs?: string[];
  bullets?: { title?: string; text: string }[];
  table?: {
    headers: string[];
    rows: string[][];
  };
  steps?: { step: string; title: string; detail: string }[];
  callout?: { title: string; text: string };
}

export interface BlogPost {
  id: string;
  slug: string;
  category: 'austria' | 'germany' | 'investment' | 'academic' | 'work'
  | 'france' | 'greece' | 'spain' | 'uk' | 'hungary';
  categoryLabel: string;
  title: string;
  seoTitle?: string;
  seoDescription?: string;
  /** 40-60 词答案优先摘要 — AIO 核心 */
  answerFirst: string;
  excerpt: string;
  image: { src: string; alt: string; width: number; height: number; };
  author: {
    name: string;
    role: string;
    credentials: string;
    office: string;
    avatar: string;
    profileUrl?: string;
  };
  reviewer?: {
    name: string;
    office: string;
    address?: string;
  };
  date: string;
  dateModified: string;
  readTime: string;
  views: number;
  tags: string[];
  legalReference: string;
  officialSource: { label: string; url: string };
  officialSources?: { label: string; url: string }[];
  relatedPages?: { title: string; href: string; page?: string; desc: string }[];
  fullArticle: {
    intro: string;
    keyPoints: string[];
    lawyerAdvice: string;
    faq: { q: string; a: string }[];
    sections?: BlogArticleSection[];
    howToSteps?: { name: string; text: string }[];
  };
}

