      'دپارتمان ارزیابی ریسک هلدینگ مهاجرتی دیاکو در سال‌های ۲۰۲۶ و ۲۰۲۷ به‌طور صریح مهاجرت به ۵ دسته از مقاصد را برای اکثر متقاضیان ایرانی توصیه نمی‌کند: ۱) جزایر کارائیب (دومینیکا، سنت‌کیتس و...) برای پاسپورت دوم (هزینه بالای ۲۰۰ هزار دلار، عدم امکان زندگی واقعی و ریسک انسداد بانکی)، ۲) کشورهای غیرشینگن شرق اروپا (صربستان، گرجستان و ارمنستان) به‌دلیل عدم عضویت در شینگن و بی‌اعتباری در اروپای غربی، ۳) استرالیا و بریتانیا برای متقاضیان بالای ۳۵ سال با بودجه متوسط، ۴) تحصیل کارشناسی/ارشد آمریکا بدون فاند کامل (ریجکتی بالای F-1 و هزینه ۴۰–۶۰ هزار دلاری)، و ۵) مهاجرت کاری به حاشیه خلیج فارس با «ویزای آزاد» (Free Visa) بدون قرارداد واقعی.',
