      keyPoints: ['امتیازدهی ۲۰۲۶: مدرک معادل کامل (۴) یا جزئی (۲)، زبان آلمانی B2 (۳) / B1 (۲) / انگلیسی B2 (۱)، سن زیر ۳۵ (۲) / زیر ۴۰ (۱)، سابقه ۲+ سال (۲).', 'اثبات مالی: Sperrkonto با €۱,۰۹۱ خالص/ماه برای ۱۲ ماه — یا قرارداد کاری پاره‌وقت (۲۰ ساعت/هفته).', 'پس از یافتن شغل با حقوق Blue Card (€۴۸,۳۰۰ عمومی / €۴۳,۷۵۹.۸۰ مشاغل کمبود برای ۲۰۲۵)، تبدیل فوری امکان‌پذیر است.', 'مدت اقامت ۱ ساله قابل تمدید در صورت اثبات پیشرفت در جستجوی کار.'],
      lawyerAdvice: 'تأییدیه ZAB (ارزیابی مدرک) گلوگاه اصلی است — تا ۳ ماه طول می‌کشد. قبل از رزرو وقت سفارت، Anabin را چک کنید و در صورت نیاز درخواست ZAB بدهید.',
      faq: [{ q: 'آیا با کارت شانس می‌توانم کار پاره‌وقت کنم؟', a: 'بله، تا ۲۰ ساعت در هفته در طول جستجو، یا به‌صورت تمام‌وقت برای دوره آزمایشی (۲ هفته).' }, { q: 'آیا مدرک زبان انگلیسی کافی است؟', a: 'برای رشته‌های فنی/IT، انگلیسی B2 در ترکیب با سایر معیارها می‌تواند ۶ امتیاز را تکمیل کند.' }],
