/* ============================================================
   3. 结构化数据生成器
   ============================================================ */
const generateBlogSchema = (posts: BlogPost[]) => ({
  '@context': 'https://schema.org',
  '@graph': [
    {
      '@type': 'Organization',
      '@id': 'https://www.dia-co.ir/#organization',
      name: 'هلدینگ مهاجرتی دیاکو',
      url: 'https://www.dia-co.ir',
      logo: 'https://www.dia-co.ir/logo.png',
      sameAs: ['https://www.linkedin.com/company/diaco-holding'],
    },
    {
      '@type': 'Blog',
      '@id': 'https://www.dia-co.ir/blog#blog',
      name: 'وبلاگ تخصصی مهاجرت دیاکو',
      description: 'تحلیل‌های حقوقی و اخبار مهاجرتی اروپا توسط وکلای مقیم وین، آتن و برلین.',
      url: 'https://www.dia-co.ir/blog',
      publisher: { '@id': 'https://www.dia-co.ir/#organization' },
      inLanguage: 'fa-IR',
    },
    ...posts.map((post) => {
      // محاسبه دقیق تعداد کلمات (نه طول کاراکتر)
      const fullText = [
        post.answerFirst,
        post.fullArticle.intro,
        ...post.fullArticle.keyPoints,
        post.fullArticle.lawyerAdvice,
        ...post.fullArticle.faq.flatMap((f) => [f.q, f.a]),
      ].join(' ');
      const wordCount = fullText.split(/\s+/).filter(Boolean).length;

      return {
        '@type': 'BlogPosting',
        '@id': `https://www.dia-co.ir/blog/${post.slug}#article`,
        headline: post.title,
        description: post.answerFirst,
        image: {
          '@type': 'ImageObject',
          url: post.image.src,
          width: post.image.width,
          height: post.image.height,
          caption: post.image.alt,
        },
        author: {
          '@type': 'Person',
          name: post.author.name,
          jobTitle: post.author.role,
          worksFor: { '@id': 'https://www.dia-co.ir/#organization' },
        },
        publisher: { '@id': 'https://www.dia-co.ir/#organization' },
        datePublished: post.date,
        dateModified: post.dateModified,
        mainEntityOfPage: `https://www.dia-co.ir/blog/${post.slug}`,
        articleSection: post.categoryLabel,
        keywords: post.tags.join(', '),
        inLanguage: 'fa-IR',
        wordCount,
        isAccessibleForFree: true,
        speakable: {
          '@type': 'SpeakableSpecification',
          cssSelector: ['h2', '.answer-first'],
        },
      };
    }),
    {
      '@type': 'BreadcrumbList',
      '@id': 'https://www.dia-co.ir/blog#breadcrumb',
      itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'خانه', item: 'https://www.dia-co.ir' },
        { '@type': 'ListItem', position: 2, name: 'وبلاگ', item: 'https://www.dia-co.ir/blog' },
      ],
    },
  ],
});

/* ============================================================
   4. 主组件
   ============================================================ */
interface Props {
  onOpenAssessment: () => void;
  onNavigateToPost?: (slug: string) => void;
  onNavigateToBlog?: () => void;
}

export type BlogSortOption = 'default' | 'popular' | 'read_time' | 'alphabetical';

const BLOG_SORT_OPTIONS: { id: BlogSortOption; label: string; icon: string }[] = [
  { id: 'default', label: 'جدیدترین مقالات', icon: '⚡' },
  { id: 'popular', label: 'پربازدیدترین', icon: '🔥' },
  { id: 'read_time', label: 'طولانی‌ترین تحلیل‌ها', icon: '⏱' },
  { id: 'alphabetical', label: 'الفبایی (الف - ی)', icon: '🔤' },
];

export const ImmigrationBlogSection: React.FC<Props> = ({
  onOpenAssessment,
  onNavigateToPost,
  onNavigateToBlog,
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('austria');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sortBy, setSortBy] = useState<BlogSortOption>('default');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoplay, setIsAutoplay] = useState(true);
  const [isPaused, setIsPaused] = useState(false);
  const [desktopCardsCount, setDesktopCardsCount] = useState<3 | 4>(4);
  const [windowWidth, setWindowWidth] = useState<number>(
    typeof window !== 'undefined' ? window.innerWidth : 1280
  );
  const [activeArticle, setActiveArticle] = useState<BlogPost | null>(null);
  const [readingProgress, setReadingProgress] = useState(0);
  const modalRef = useRef<HTMLDivElement>(null);
  const sectionId = useId();

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // محاسبه تعداد کارت‌های قابل نمایش بر اساس درخواست کاربر:
  // در نمایشگر بزرگ 4 یا 3 تا کارت، در تبلت 2 تا، و برای موبایل 1 کارت
  const visibleCount = useMemo(() => {
    if (windowWidth < 768) return 1; // موبایل: ۱ کارت
    if (windowWidth < 1024) return 2; // تبلت: ۲ کارت
    if (windowWidth < 1280) return 3; // نمایشگر متوسط: ۳ کارت
    return desktopCardsCount; // نمایشگر بزرگ دسکتاپ: ۴ یا ۳ کارت
  }, [windowWidth, desktopCardsCount]);

const categories = [
  { id: 'austria', label: 'اتریش (NAG)' },
  { id: 'germany', label: 'آلمان (AufenthG)' },
  { id: 'france', label: 'فرانسه (Passeport Talent)' },
  { id: 'greece', label: 'یونان (Golden Visa)' },
  { id: 'spain', label: 'اسپانیا (DNV/NLV)' },
  { id: 'uk', label: 'انگلستان (Skilled Worker)' },
  { id: 'hungary', label: 'مجارستان (Guest Investor)' },
  { id: 'investment', label: 'گلدن ویزا و ملک' },
  { id: 'work', label: 'ویزای کاری' },
  { id: 'academic', label: 'تحصیلی و بورسیه' },
];

  const filteredPosts = useMemo(() => {
    return BLOG_POSTS.filter((post) => {
      const matchesCategory = post.category === selectedCategory;
      const q = searchQuery.trim().toLowerCase();
      const matchesSearch = q === '' ||
        post.title.toLowerCase().includes(q) ||
        post.answerFirst.toLowerCase().includes(q) ||
        post.tags.some((t) => t.toLowerCase().includes(q));
      return matchesCategory && matchesSearch;
    });
  }, [selectedCategory, searchQuery]);

  // سورت مقالات
  const sortedPosts = useMemo(() => {
    const list = [...filteredPosts];
    switch (sortBy) {
      case 'popular':
        return list.sort((a, b) => (b.views || 0) - (a.views || 0));
      case 'read_time':
        return list.sort((a, b) => parseInt(b.readTime) - parseInt(a.readTime));
      case 'alphabetical':
        return list.sort((a, b) => a.title.localeCompare(b.title, 'fa'));
      default:
        return list;
    }
  }, [filteredPosts, sortBy]);

  const maxIndex = Math.max(0, sortedPosts.length - visibleCount);

  // ریست ایندکس با تغییر دسته‌بندی، جستجو، سورت یا سایز صفحه
  useEffect(() => {
    setCurrentIndex(0);
  }, [selectedCategory, searchQuery, sortBy, visibleCount]);

  // چرخش اتوماتیک اسلایدر با مکث روی هاور
  useEffect(() => {
    if (!isAutoplay || isPaused || sortedPosts.length <= visibleCount) return;
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev >= maxIndex ? 0 : prev + 1));
    }, 4500);
    return () => clearInterval(interval);
  }, [isAutoplay, isPaused, sortedPosts.length, visibleCount, maxIndex]);

  const handleNext = () => {
    setCurrentIndex((prev) => (prev >= maxIndex ? 0 : prev + 1));
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev <= 0 ? maxIndex : prev - 1));
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    setIsPaused(true);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const handleTouchEnd = () => {
    if (touchStartX.current !== null && touchEndX.current !== null) {
      const diff = touchStartX.current - touchEndX.current;
      if (diff > 40) {
        handleNext();
      } else if (diff < -40) {
        handlePrev();
      }
    }
    touchStartX.current = null;
    touchEndX.current = null;
    setIsPaused(false);
  };

  const jsonLd = useMemo(() => generateBlogSchema(BLOG_POSTS), []);

  /* 阅读进度条 */
  useEffect(() => {
    if (!activeArticle) {
      setReadingProgress(0);
      return;
    }
    const el = modalRef.current;
    if (!el) return;
    const handleScroll = () => {
      const total = el.scrollHeight - el.clientHeight;
      const scrolled = el.scrollTop;
      setReadingProgress(total > 0 ? (scrolled / total) * 100 : 0);
    };
    el.addEventListener('scroll', handleScroll, { passive: true });
    return () => el.removeEventListener('scroll', handleScroll);
  }, [activeArticle]);

  return (
    <section id="blog" dir="rtl" className="scroll-mt-24 bg-white py-16 md:py-24 text-slate-800" aria-labelledby={`${sectionId}-title`}>
      <script type="application/ld+json">{JSON.stringify(jsonLd)}</script>

      <div className="container mx-auto px-4 md:px-8">
        {/* ===== Header ===== */}
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 border-b border-slate-200 pb-8">
          <div className="max-w-2xl">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="rounded-full bg-[#082833] text-amber-300 px-3.5 py-1 text-xs font-bold inline-flex items-center gap-1.5">
                <ShieldCheck className="h-3.5 w-3.5" />
                بینش حقوقی تأییدشده
              </span>
              <span className="text-xs font-semibold text-slate-500 flex items-center gap-1">
                <UserCheck className="h-3.5 w-3.5 text-emerald-500" />
                نگارش وکلای مقیم وین و آتن | بازبینی: ۲۰۲۶-۱۰-۲۵
              </span>
            </div>
            <h2 id={`${sectionId}-title`} className="mt-3 text-2xl sm:text-4xl font-black text-[#082833]">
              وبلاگ تخصصی مهاجرت اروپا ۲۰۲۶
            </h2>
            <p className="mt-2 text-xs sm:text-sm text-slate-600 leading-relaxed">
              <strong className="text-slate-900">خلاصه:</strong> تحلیل مستند مصوبات پارلمان اتریش و آلمان، سهمیه‌های تمکن مالی، گلدن ویزای یونان و تغییرات AI Overviews — با استناد به ماده قانونی (NAG، AufenthG، Law 5100/2024) و تأیید وکلای پایه یک.
            </p>
          </div>

          {/* Action Button & Search */}
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2.5">
            {onNavigateToBlog && (
              <button
                type="button"
                onClick={onNavigateToBlog}
                className="rounded-2xl border border-[#082833] bg-[#082833] hover:bg-[#0c3644] text-amber-300 px-4 py-2.5 text-xs font-black transition cursor-pointer flex items-center justify-center gap-1.5 shadow-sm"
              >
                <span>صفحه اختصاصی و آرشیو کامل ({BLOG_POSTS.length} مقاله)</span>
                <ArrowRight className="h-3.5 w-3.5 rotate-180" />
              </button>
            )}
            <div className="w-full sm:w-60 relative">
              <input
                type="search"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="جستجو در مقالات..."
                className="w-full rounded-2xl border border-slate-300 bg-slate-50 py-2.5 pr-10 pl-4 text-xs font-semibold focus:border-[#082833] focus:bg-white focus:outline-none"
                aria-label="جستجو در مقالات"
              />
              <Search className="absolute right-3.5 top-2.5 h-4 w-4 text-slate-400" />
            </div>
          </div>
        </div>

        {/* ===== Category Tabs ===== */}
        <div className="mt-6 flex overflow-x-auto gap-2 pb-2" role="tablist" aria-label="دسته‌بندی مقالات">
          {categories.map((cat) => (
            <button
              key={cat.id}
              type="button"
              role="tab"
              aria-selected={selectedCategory === cat.id}
              onClick={() => setSelectedCategory(cat.id)}
              className={`rounded-xl px-4 py-2 text-xs font-bold transition whitespace-nowrap cursor-pointer ${
                selectedCategory === cat.id
                  ? 'bg-[#082833] text-amber-300 shadow-md'
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>

        {/* نوار کنترل اسلایدر مقالات، سورتینگ و تعداد کارت‌ها */}
        <div className="mt-6 flex flex-wrap items-center justify-between gap-3 bg-slate-50 border border-slate-200 rounded-2xl p-3 sm:p-4 shadow-xs">
          {/* بخش سورت شدن مقالات */}
          <div className="flex items-center gap-2 flex-wrap text-xs">
            <span className="text-[#082833] font-bold flex items-center gap-1">
              <span>⇅</span>
              <span>سورت مقالات:</span>
            </span>
            <div className="flex items-center gap-1 flex-wrap">
              {BLOG_SORT_OPTIONS.map((opt) => {
                const isSelected = sortBy === opt.id;
                return (
                  <button
                    key={opt.id}
                    type="button"
                    onClick={() => setSortBy(opt.id)}
                    className={`px-2.5 py-1.5 rounded-xl text-[11px] font-bold transition flex items-center gap-1 cursor-pointer ${
                      isSelected
                        ? 'bg-[#082833] text-amber-300 shadow-md font-black'
                        : 'bg-white text-slate-600 hover:bg-slate-200 border border-slate-200'
                    }`}
                  >
                    <span>{opt.icon}</span>
                    <span>{opt.label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* کنترل‌های اسلایدر و تنظیمات نمایش در دسکتاپ */}
          <div className="flex items-center gap-2.5 flex-wrap justify-between sm:justify-end w-full sm:w-auto">
            {/* کلید تغییر تعداد کارت در دسکتاپ (۳ یا ۴ تایی) */}
            {windowWidth >= 1280 && (
              <div className="hidden xl:flex items-center gap-1 bg-white border border-slate-200 p-1 rounded-xl text-[11px]">
                <span className="text-slate-500 px-1.5 font-medium">نمایش دسکتاپ:</span>
                <button
                  type="button"
                  onClick={() => setDesktopCardsCount(4)}
                  className={`px-2.5 py-1 rounded-lg font-bold transition cursor-pointer ${
                    desktopCardsCount === 4
                      ? 'bg-[#082833] text-amber-300 font-black'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                  title="نمایش ۴ مقاله در نمایشگر بزرگ"
                >
                  ۴ کارت
                </button>
                <button
                  type="button"
                  onClick={() => setDesktopCardsCount(3)}
                  className={`px-2.5 py-1 rounded-lg font-bold transition cursor-pointer ${
                    desktopCardsCount === 3
                      ? 'bg-[#082833] text-amber-300 font-black'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                  title="نمایش ۳ مقاله در نمایشگر بزرگ"
                >
                  ۳ کارت
                </button>
              </div>
            )}

            {/* نشانگر اسلاید فعلی */}
            <div className="flex items-center gap-2">
              <span className="text-[11px] text-slate-600 font-bold bg-white px-2.5 py-1.5 rounded-xl border border-slate-200">
                مقاله {sortedPosts.length > 0 ? currentIndex + 1 : 0} تا {Math.min(currentIndex + visibleCount, sortedPosts.length)} از {sortedPosts.length}
              </span>

              {/* دکمه توقف / فعال‌سازی پخش خودکار */}
              <button
                type="button"
                onClick={() => setIsAutoplay(!isAutoplay)}
                className={`px-2.5 py-1.5 rounded-xl text-[11px] font-bold border transition flex items-center gap-1.5 cursor-pointer ${
                  isAutoplay && !isPaused
                    ? 'border-emerald-500/40 text-emerald-700 bg-emerald-50'
                    : 'border-slate-300 text-slate-600 bg-white hover:bg-slate-100'
                }`}
                title={isAutoplay ? 'توقف اسلایدر خودکار' : 'فعال‌سازی اسلایدر خودکار'}
              >
                <span className={`inline-block h-2 w-2 rounded-full ${isAutoplay && !isPaused ? 'bg-emerald-500 animate-pulse' : 'bg-slate-400'}`} />
                <span>{isAutoplay && !isPaused ? 'خودکار فعال' : 'متوقف'}</span>
              </button>

              {/* دکمه‌های ناوبری قبلی و بعدی */}
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={handlePrev}
                  className="w-8 h-8 rounded-xl bg-white hover:bg-[#082833] hover:text-amber-300 text-[#082833] border border-slate-300 flex items-center justify-center text-sm font-black transition cursor-pointer shadow-xs"
                  title="مقاله قبلی"
                  aria-label="مقاله قبلی"
                >
                  →
                </button>
                <button
                  type="button"
                  onClick={handleNext}
                  className="w-8 h-8 rounded-xl bg-white hover:bg-[#082833] hover:text-amber-300 text-[#082833] border border-slate-300 flex items-center justify-center text-sm font-black transition cursor-pointer shadow-xs"
                  title="مقاله بعدی"
                  aria-label="مقاله بعدی"
                >
                  ←
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* کانتینر اسلایدر اتوماتیک به جای گرید استاتیک */}
        {sortedPosts.length === 0 ? (
          <div className="mt-8 rounded-3xl border border-slate-200 bg-slate-50 p-12 text-center">
            <p className="text-sm font-bold text-slate-600">
              مقاله‌ای در این دسته یا با این جستجو یافت نشد.
            </p>
            <p className="mt-2 text-xs text-slate-400">
              لطفاً دسته دیگری را انتخاب کنید یا عبارت جستجو را تغییر دهید.
            </p>
            <button
              type="button"
              onClick={() => {
                setSelectedCategory('austria');
                setSearchQuery('');
                setSortBy('default');
              }}
              className="mt-4 rounded-xl bg-[#082833] text-amber-300 px-4 py-2 text-xs font-black cursor-pointer shadow-sm"
            >
              نمایش مقالات اتریش
            </button>
          </div>
        ) : (
          <div
            className="relative mt-8 group/blogslider"
            onMouseEnter={() => setIsPaused(true)}
            onMouseLeave={() => setIsPaused(false)}
          >
            {/* دکمه شناور قبلی (سمت راست در RTL) */}
            <button
              type="button"
              onClick={handlePrev}
              className="absolute -right-3 sm:-right-5 top-1/2 -translate-y-1/2 z-20 w-10 h-10 rounded-full bg-white hover:bg-[#082833] hover:text-amber-300 text-[#082833] border border-slate-300 shadow-xl flex items-center justify-center text-base font-black transition-all opacity-80 group-hover/blogslider:opacity-100 hover:scale-110 cursor-pointer backdrop-blur-md"
              title="مقاله قبلی"
              aria-label="مقاله قبلی"
            >
              →
            </button>

            {/* دکمه شناور بعدی (سمت چپ در RTL) */}
            <button
              type="button"
              onClick={handleNext}
              className="absolute -left-3 sm:-left-5 top-1/2 -translate-y-1/2 z-20 w-10 h-10 rounded-full bg-white hover:bg-[#082833] hover:text-amber-300 text-[#082833] border border-slate-300 shadow-xl flex items-center justify-center text-base font-black transition-all opacity-80 group-hover/blogslider:opacity-100 hover:scale-110 cursor-pointer backdrop-blur-md"
              title="مقاله بعدی"
              aria-label="مقاله بعدی"
            >
              ←
            </button>

            {/* تراک اسلایدر با انیمیشن روان و تنظیم دقیق پهنای کارت بر اساس دستگاه */}
            <div className="overflow-hidden rounded-3xl" dir="ltr">
              <div
                className="flex transition-transform duration-500 ease-out"
                style={{
                  transform: `translateX(-${currentIndex * (100 / visibleCount)}%)`,
                }}
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
              >
                {sortedPosts.map((post) => (
                  <div
                    key={post.id}
                    style={{ width: `${100 / visibleCount}%` }}
                    className="shrink-0 p-2 sm:p-2.5 h-full"
                    dir="rtl"
                  >
                    <article
                      itemScope
                      itemType="https://schema.org/BlogPosting"
                      className="group flex flex-col h-full rounded-3xl border border-slate-200 bg-white overflow-hidden shadow-soft transition-all duration-300 hover:-translate-y-1 hover:border-[#f5a623] hover:shadow-xl"
                    >
                      {/* Featured Image */}
                      <div className="relative aspect-[16/9] overflow-hidden bg-slate-100 shrink-0">
                        <img
                          src={post.image.src}
                          alt={post.image.alt}
                          width={post.image.width}
                          height={post.image.height}
                          loading="lazy"
                          decoding="async"
                          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                          itemProp="image"
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent" />
                        <span className="absolute top-3 right-3 rounded-full bg-black/60 px-2.5 py-1 text-[10px] font-bold text-white backdrop-blur-md">
                          {post.categoryLabel}
                        </span>
                        <span className="absolute top-3 left-3 flex items-center gap-1 rounded-full bg-white/90 px-2 py-0.5 text-[10px] font-bold text-slate-700">
                          <Clock className="h-3 w-3" /> {post.readTime}
                        </span>
                      </div>

                      <div className="p-5 flex flex-col flex-1 justify-between">
                        <div>
                          {/* Answer-First */}
                          <p className="answer-first text-[11px] leading-6 text-slate-600 bg-amber-50/60 border border-amber-100 rounded-xl p-3 mb-3 line-clamp-3" itemProp="description">
                            {post.answerFirst}
                          </p>

                          <h3 className="text-sm font-black leading-snug text-[#082833] group-hover:text-amber-600 transition-colors line-clamp-2" itemProp="headline">
                            <a
                              href={`/blog/${post.slug}`}
                              onClick={(e) => {
                                if (!e.ctrlKey && !e.metaKey) {
                                  e.preventDefault();
                                  if (onNavigateToPost) onNavigateToPost(post.slug);
                                  else window.location.pathname = `/blog/${post.slug}`;
                                }
                              }}
                              className="hover:underline"
                            >
                              {post.title}
                            </a>
                          </h3>

                          {/* Tags */}
                          <div className="mt-3 flex flex-wrap gap-1.5">
                            {post.tags.slice(0, 3).map((tag) => (
                              <span key={tag} className="rounded-lg bg-slate-100 px-2 py-0.5 text-[10px] font-semibold text-slate-600">
                                #{tag}
                              </span>
                            ))}
                          </div>
                        </div>

                        {/* Author + CTA */}
                        <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between gap-2">
                          <div className="flex items-center gap-2 min-w-0">
                            <span className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-[#082833] text-white text-sm" aria-hidden="true">
                              {post.author.avatar}
                            </span>
                            <div className="min-w-0">
                              <p className="text-[10px] font-bold text-[#082833] truncate" itemProp="author">{post.author.name}</p>
                              <p className="text-[9px] text-slate-500 truncate">{post.author.credentials}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-1.5 shrink-0">
                            <a
                              href={`/blog/${post.slug}`}
                              onClick={(e) => {
                                if (!e.ctrlKey && !e.metaKey) {
                                  e.preventDefault();
                                  if (onNavigateToPost) onNavigateToPost(post.slug);
                                  else window.location.pathname = `/blog/${post.slug}`;
                                }
                              }}
                              className="rounded-xl bg-amber-400 hover:bg-amber-300 px-3 py-1.5 text-[10px] font-black text-[#082833] transition shadow-xs cursor-pointer inline-flex items-center gap-1"
                            >
                              صفحه اختصاصی <ArrowRight className="h-3 w-3" />
                            </a>
                            <button
                              type="button"
                              onClick={() => setActiveArticle(post)}
                              className="rounded-xl bg-slate-100 hover:bg-slate-200 px-2 py-1.5 text-[10px] font-bold text-slate-700 transition cursor-pointer"
                              title="مرور سریع"
                            >
                              مرور سریع
                            </button>
                          </div>
                        </div>
                      </div>
                    </article>
                  </div>
                ))}
              </div>
            </div>

            {/* نقاط نشانگر صفحه (Pagination Dots) */}
            {maxIndex > 0 && (
              <div className="mt-6 flex items-center justify-center gap-1.5">
                {Array.from({ length: maxIndex + 1 }).map((_, idx) => {
                  const isActive = currentIndex === idx;
                  return (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => setCurrentIndex(idx)}
                      className={`h-2 rounded-full transition-all duration-300 cursor-pointer ${
                        isActive
                          ? 'w-8 bg-[#082833] shadow-md'
                          : 'w-2 bg-slate-300 hover:bg-slate-400'
                      }`}
                      aria-label={`اسلاید ${idx + 1}`}
                      title={`مشاهده اسلاید ${idx + 1}`}
                    />
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ===== Newsletter ===== */}
        <div className="mt-14 rounded-3xl bg-gradient-to-r from-[#082833] via-[#0d3644] to-[#082833] p-6 sm:p-10 text-white shadow-xl flex flex-col lg:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="grid h-14 w-14 flex-none place-items-center rounded-2xl bg-[#f5a623] text-[#082833] text-2xl shadow-lg">📮</div>
            <div>
              <h3 className="text-lg sm:text-xl font-black">دریافت فوری تغییرات قوانین ۲۰۲۶</h3>
              <p className="mt-1 text-xs text-slate-300 max-w-lg">هشدارهای رسمی سهمیه‌ها، تغییرات NAG/AufenthG و بازگشایی ظرفیت‌ها را پیش از تکمیل دریافت کنید.</p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2.5 w-full lg:w-auto">
            <input
              type="email"
              placeholder="ایمیل خود را وارد کنید"
              className="rounded-2xl border border-white/20 bg-white/10 px-4 py-3 text-xs text-white placeholder-slate-300 focus:border-[#f5a623] focus:outline-none flex-1 min-w-[200px]"
              aria-label="ایمیل برای خبرنامه"
            />
            <button
              type="button"
              onClick={onOpenAssessment}
              className="rounded-2xl bg-gradient-to-l from-[#fed871] via-[#f5a623] to-[#e58e0b] px-6 py-3 text-xs font-black text-[#082833] shadow-lg transition hover:scale-105 cursor-pointer"
            >
              عضویت در خبرنامه
            </button>
          </div>
        </div>
      </div>

      {/* ===== Article Modal ===== */}
      {activeArticle && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="article-title"
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
          onClick={() => setActiveArticle(null)}
        >
          <div
            ref={modalRef}
            onClick={(e) => e.stopPropagation()}
            className="relative max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-3xl bg-white shadow-2xl text-slate-800"
          >
            {/* Reading Progress */}
            <div className="sticky top-0 z-10 h-1 bg-slate-200">
              <div className="h-full bg-gradient-to-l from-[#fed871] to-[#f5a623] transition-[width] duration-150" style={{ width: `${readingProgress}%` }} />
            </div>

            <button
              type="button"
              onClick={() => setActiveArticle(null)}
              className="absolute top-4 left-4 z-20 grid h-9 w-9 place-items-center rounded-xl border border-slate-200 bg-white/90 text-slate-500 hover:bg-slate-100 cursor-pointer"
              aria-label="بستن مقاله"
            >
              <X className="h-4 w-4" />
            </button>

            <div className="p-6 sm:p-8">
              {/* Header */}
              <div className="flex items-center gap-2 flex-wrap">
                <span className="rounded-full bg-amber-50 border border-amber-200 px-3 py-1 text-[11px] font-black text-amber-800">
                  {activeArticle.categoryLabel}
                </span>
                <span className="text-[11px] text-slate-400 flex items-center gap-1">
                  <Calendar className="h-3 w-3" /> {activeArticle.date}
                </span>
                <span className="text-[11px] text-emerald-600 font-bold flex items-center gap-1">
                  <CheckCircle2 className="h-3 w-3" /> بازبینی: {activeArticle.dateModified}
                </span>
              </div>

              <h2 id="article-title" className="mt-3 text-lg sm:text-2xl font-black text-[#082833] leading-snug">
                {activeArticle.title}
              </h2>

              {/* Author Profile */}
              <div className="mt-4 flex items-center gap-3 border-y border-slate-100 py-3">
                <span className="grid h-11 w-11 place-items-center rounded-2xl bg-[#082833] text-white text-lg" aria-hidden="true">
                  {activeArticle.author.avatar}
                </span>
                <div>
                  <h4 className="text-xs sm:text-sm font-black text-[#082833]">{activeArticle.author.name}</h4>
                  <p className="text-[10px] text-slate-500 font-semibold">{activeArticle.author.role} — {activeArticle.author.office}</p>
                  <p className="text-[9px] text-emerald-600 font-bold">{activeArticle.author.credentials}</p>
                </div>
              </div>

              {/* Answer-First */}
              <div className="mt-5 rounded-2xl bg-amber-50/80 border border-amber-200/60 p-4">
                <div className="flex items-center gap-2 text-[11px] font-bold text-amber-800 mb-1.5">
                  <Quote className="h-3.5 w-3.5" /> پاسخ سریع (Answer First)
                </div>
                <p className="text-xs leading-7 text-amber-950 font-medium">{activeArticle.answerFirst}</p>
              </div>

              {/* Intro */}
              <p className="mt-5 text-xs sm:text-sm leading-7 text-slate-700 text-justify">{activeArticle.fullArticle.intro}</p>

              {/* Key Points */}
              <h4 className="mt-6 text-sm font-black text-[#082833] flex items-center gap-2">
                <List className="h-4 w-4 text-amber-500" /> نکات کلیدی ۲۰۲۶
              </h4>
              <ul className="mt-3 space-y-2.5">
                {activeArticle.fullArticle.keyPoints.map((pt, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-xs leading-6 text-slate-700">
                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                    <span>{pt}</span>
                  </li>
                ))}
              </ul>

              {/* Legal Reference */}
              <div className="mt-6 rounded-2xl border border-blue-200 bg-blue-50/60 p-4">
                <div className="flex items-center gap-2 text-[11px] font-bold text-blue-800 mb-1">
                  <Scale className="h-3.5 w-3.5" /> مستند قانونی رسمی
                </div>
                <p className="text-xs font-semibold text-blue-950" dir="ltr">{activeArticle.legalReference}</p>
                <a
                  href={activeArticle.officialSource.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-2 inline-flex items-center gap-1 text-[10px] font-bold text-blue-700 hover:text-blue-900"
                >
                  منبع رسمی: {activeArticle.officialSource.label}
                  <ExternalLink className="h-3 w-3" />
                </a>
              </div>

              {/* Lawyer Advice */}
              <div className="mt-4 rounded-2xl border border-amber-200 bg-amber-50/70 p-4">
                <div className="flex items-center gap-2 text-[11px] font-bold text-amber-800 mb-1">
                  <Award className="h-3.5 w-3.5" /> دیدگاه وکیل مقیم دیاکو
                </div>
                <p className="text-xs leading-6 text-amber-950 font-medium">{activeArticle.fullArticle.lawyerAdvice}</p>
              </div>

              {/* FAQ */}
              <div className="mt-6">
                <h4 className="text-sm font-black text-[#082833] mb-3">پرسش‌های متداول</h4>
                <div className="space-y-2">
                  {activeArticle.fullArticle.faq.map((item, idx) => (
                    <details key={idx} className="rounded-xl border border-slate-200 bg-slate-50/50 overflow-hidden group">
                      <summary className="flex items-center justify-between p-3 cursor-pointer text-xs font-bold text-slate-700 list-none">
                        {item.q}
                        <ChevronDown className="h-3.5 w-3.5 text-slate-400 group-open:rotate-180 transition-transform" />
                      </summary>
                      <p className="px-3 pb-3 text-[11px] leading-6 text-slate-600 border-t border-slate-200 pt-2">{item.a}</p>
                    </details>
                  ))}
                </div>
              </div>

              {/* Footer CTA */}
              <div className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    const slugToOpen = activeArticle.slug;
                    setActiveArticle(null);
                    if (onNavigateToPost) {
                      onNavigateToPost(slugToOpen);
                    } else {
                      window.location.pathname = `/blog/${slugToOpen}`;
                    }
                  }}
                  className="rounded-xl border border-amber-400/50 bg-amber-400/10 hover:bg-amber-400/20 text-[#082833] font-black px-4 py-2 text-xs transition cursor-pointer inline-flex items-center gap-1.5"
                >
                  <span>مشاهده در صفحه کامل با URL اختصاصی</span>
                  <ExternalLink className="h-3.5 w-3.5 text-amber-600" />
                </button>
                <button
                  type="button"
                  onClick={() => { setActiveArticle(null); onOpenAssessment(); }}
                  className="rounded-xl bg-gradient-to-l from-[#fed871] via-[#f5a623] to-[#e58e0b] px-5 py-2 text-xs font-black text-[#082833] shadow-lg transition hover:scale-105 cursor-pointer inline-flex items-center gap-1.5"
                >
                  ارزیابی شانس من در این مسیر <ArrowRight className="h-3.5 w-3.5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default ImmigrationBlogSection;